def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid separator.
    sep_col = next((c for c in range(w)
                    if len(set(grid[r][c] for r in range(h))) == 1), None)
    if sep_col is not None:
        n = sep_col
        right = [row[sep_col + 1:sep_col + 1 + n] for row in grid]
        out = []
        for r in range(h):
            bg = max(set(right[r]), key=right[r].count)
            out.append([3 if grid[r][c] == right[r][c] else bg
                        for c in range(n)])
        return out

    sep_row = next(r for r in range(h) if len(set(grid[r])) == 1)
    n = sep_row
    out = []
    for r in range(n):
        bottom = grid[sep_row + 1 + r]
        bg = max(set(bottom), key=bottom.count)
        out.append([3 if grid[r][c] == bottom[c] else bg
                    for c in range(w)])
    return out
